sources/service_plan.schema.json:
{
  "$defs": {
    "ChargingStationPlan": {
      "additionalProperties": false,
      "properties": {
        "zone_id": {
          "title": "Zone Id",
          "type": "string"
        },
        "chargers": {
          "maximum": 100,
          "minimum": 1,
          "title": "Chargers",
          "type": "integer"
        },
        "month_in_phase": {
          "default": 1,
          "maximum": 4,
          "minimum": 1,
          "title": "Month In Phase",
          "type": "integer"
        }
      },
      "required": [
        "zone_id",
        "chargers"
      ],
      "title": "ChargingStationPlan",
      "type": "object"
    },
    "ProductId": {
      "enum": [
        "drone",
        "bike",
        "scooter"
      ],
      "title": "ProductId",
      "type": "string"
    },
    "ProductServiceAllocation": {
      "additionalProperties": false,
      "description": "Dedicate integer vehicles of a product to compatible approved services.",
      "properties": {
        "product_id": {
          "$ref": "#/$defs/ProductId"
        },
        "services": {
          "items": {
            "$ref": "#/$defs/ServiceCapacityShare"
          },
          "minItems": 1,
          "title": "Services",
          "type": "array"
        }
      },
      "required": [
        "product_id",
        "services"
      ],
      "title": "ProductServiceAllocation",
      "type": "object"
    },
    "ProductZoneDistribution": {
      "additionalProperties": false,
      "description": "Phase policy for placing every available vehicle of one product.",
      "properties": {
        "product_id": {
          "$ref": "#/$defs/ProductId"
        },
        "zones": {
          "items": {
            "$ref": "#/$defs/ZoneFleetShare"
          },
          "minItems": 1,
          "title": "Zones",
          "type": "array"
        }
      },
      "required": [
        "product_id",
        "zones"
      ],
      "title": "ProductZoneDistribution",
      "type": "object"
    },
    "ServiceCapacityShare": {
      "additionalProperties": false,
      "properties": {
        "service_id": {
          "$ref": "#/$defs/ServiceId"
        },
        "allocation_pct": {
          "description": "Percentage from 0 to 100; zero explicitly leaves this service unassigned.",
          "maximum": 100,
          "minimum": 0,
          "title": "Allocation Pct",
          "type": "number"
        }
      },
      "required": [
        "service_id",
        "allocation_pct"
      ],
      "title": "ServiceCapacityShare",
      "type": "object"
    },
    "ServiceId": {
      "enum": [
        "passenger_transport",
        "food_delivery",
        "package_delivery"
      ],
      "title": "ServiceId",
      "type": "string"
    },
    "ServiceMonthlyPlan": {
      "additionalProperties": false,
      "properties": {
        "month_in_phase": {
          "maximum": 4,
          "minimum": 1,
          "title": "Month In Phase",
          "type": "integer"
        },
        "prices": {
          "items": {
            "$ref": "#/$defs/ServicePrice"
          },
          "minItems": 1,
          "title": "Prices",
          "type": "array"
        },
        "fleet_distribution": {
          "items": {
            "$ref": "#/$defs/ProductZoneDistribution"
          },
          "title": "Fleet Distribution",
          "type": "array"
        },
        "service_allocations": {
          "items": {
            "$ref": "#/$defs/ProductServiceAllocation"
          },
          "title": "Service Allocations",
          "type": "array"
        },
        "vehicle_assignments": {
          "items": {
            "$ref": "#/$defs/ServiceVehicleAssignment"
          },
          "title": "Vehicle Assignments",
          "type": "array"
        },
        "service_mode": {
          "default": "dedicated",
          "enum": [
            "dedicated",
            "pooled"
          ],
          "title": "Service Mode",
          "type": "string",
          "description": "dedicated reparte vehículos entre servicios. pooled permite compartirlos y exige omitir service_allocations o dejarlo vacío."
        }
      },
      "required": [
        "month_in_phase",
        "prices"
      ],
      "title": "ServiceMonthlyPlan",
      "type": "object",
      "allOf": [
        {
          "if": {
            "properties": {
              "service_mode": {
                "const": "pooled"
              }
            },
            "required": [
              "service_mode"
            ]
          },
          "then": {
            "properties": {
              "service_allocations": {
                "maxItems": 0
              }
            }
          }
        }
      ]
    },
    "ServicePrice": {
      "additionalProperties": false,
      "properties": {
        "service_id": {
          "$ref": "#/$defs/ServiceId"
        },
        "base_fare": {
          "minimum": 0,
          "title": "Base Fare",
          "type": "number"
        },
        "price_per_km": {
          "minimum": 0,
          "title": "Price Per Km",
          "type": "number"
        }
      },
      "required": [
        "service_id",
        "base_fare",
        "price_per_km"
      ],
      "title": "ServicePrice",
      "type": "object"
    },
    "ServiceVehicleAssignment": {
      "additionalProperties": false,
      "description": "Place one owned vehicle in a powered zone for approved services.",
      "properties": {
        "asset_id": {
          "minLength": 1,
          "title": "Asset Id",
          "type": "string"
        },
        "zone_id": {
          "minLength": 1,
          "title": "Zone Id",
          "type": "string"
        },
        "services": {
          "items": {
            "$ref": "#/$defs/ServiceId"
          },
          "minItems": 1,
          "title": "Services",
          "type": "array"
        }
      },
      "required": [
        "asset_id",
        "zone_id",
        "services"
      ],
      "title": "ServiceVehicleAssignment",
      "type": "object"
    },
    "ZoneFleetShare": {
      "additionalProperties": false,
      "description": "Relative monthly deployment of one product to one operating zone.",
      "properties": {
        "zone_id": {
          "maxLength": 120,
          "minLength": 1,
          "title": "Zone Id",
          "type": "string"
        },
        "allocation_pct": {
          "description": "Percentage from 0 to 100; zero explicitly leaves this zone unused.",
          "maximum": 100,
          "minimum": 0,
          "title": "Allocation Pct",
          "type": "number"
        }
      },
      "required": [
        "zone_id",
        "allocation_pct"
      ],
      "title": "ZoneFleetShare",
      "type": "object"
    }
  },
  "additionalProperties": false,
  "description": "Human markets and campaigns are applied by the host, not copied by the agent.",
  "properties": {
    "months": {
      "items": {
        "$ref": "#/$defs/ServiceMonthlyPlan"
      },
      "maxItems": 4,
      "title": "Months",
      "type": "array"
    },
    "prices": {
      "description": "Legacy phase tariff. For monthly planning use months and leave this empty.",
      "items": {
        "$ref": "#/$defs/ServicePrice"
      },
      "title": "Prices",
      "type": "array"
    },
    "fleet_distribution": {
      "items": {
        "$ref": "#/$defs/ProductZoneDistribution"
      },
      "title": "Fleet Distribution",
      "type": "array"
    },
    "charging_investments": {
      "description": "Nueva recarga por zona y mes de apertura. Cada zona con flota necesita recarga propia activa, aunque solo haya un vehículo. Comprueba primero empresa/recarga.csv: una lista vacía sin recarga previa deja la flota inactiva. Su coste debe caber en caja con los demás compromisos.",
      "items": {
        "$ref": "#/$defs/ChargingStationPlan"
      },
      "title": "Charging Investments",
      "type": "array"
    },
    "reserve_cash": {
      "default": 0,
      "description": "Reserva adicional de caja. Se aplica el mayor valor entre esta reserva y el mínimo humano; no incluyas otra vez pagos pendientes de vehículos, recarga ni marketing aprobado.",
      "minimum": 0,
      "title": "Reserve Cash",
      "type": "number"
    },
    "target_market_share_pct": {
      "default": 15,
      "maximum": 40,
      "minimum": 1,
      "title": "Target Market Share Pct",
      "type": "number"
    }
  },
  "title": "OperationalPlan",
  "type": "object"
}

marketing/reference/campaign.schema.json:
{
  "$defs": {
    "CustomerSegment": {
      "enum": [
        "tourists",
        "young",
        "adults",
        "seniors"
      ],
      "title": "CustomerSegment",
      "type": "string"
    },
    "MarketingCampaign": {
      "additionalProperties": false,
      "properties": {
        "channel": {
          "maxLength": 80,
          "minLength": 1,
          "title": "Channel",
          "type": "string",
          "enum": [
            "search",
            "social",
            "email",
            "outdoor",
            "partners"
          ]
        },
        "budget": {
          "title": "Budget",
          "type": "number",
          "exclusiveMinimum": 0
        },
        "target_segments": {
          "items": {
            "$ref": "#/$defs/CustomerSegment"
          },
          "maxItems": 4,
          "minItems": 1,
          "title": "Target Segments",
          "type": "array"
        },
        "target_services": {
          "description": "Servicios anunciados. Vacío: todos los servicios de la estrategia aprobada. campaign-v3 permite concentrar la inversión por servicio.",
          "items": {
            "$ref": "#/$defs/ServiceId"
          },
          "maxItems": 3,
          "title": "Target Services",
          "type": "array"
        },
        "message": {
          "maxLength": 600,
          "minLength": 1,
          "title": "Message",
          "type": "string"
        },
        "frequency_per_week": {
          "anyOf": [
            {
              "maximum": 3,
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Frequency Per Week"
        },
        "start_week": {
          "anyOf": [
            {
              "maximum": 16,
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Start Week"
        },
        "end_week": {
          "anyOf": [
            {
              "maximum": 16,
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "End Week"
        },
        "call_to_action": {
          "default": "",
          "maxLength": 160,
          "title": "Call To Action",
          "type": "string"
        },
        "creative_asset_ids": {
          "items": {
            "type": "string"
          },
          "maxItems": 6,
          "title": "Creative Asset Ids",
          "type": "array"
        }
      },
      "required": [
        "channel",
        "budget",
        "target_segments",
        "message"
      ],
      "title": "MarketingCampaign",
      "type": "object"
    },
    "ServiceId": {
      "enum": [
        "passenger_transport",
        "food_delivery",
        "package_delivery"
      ],
      "title": "ServiceId",
      "type": "string"
    }
  },
  "additionalProperties": false,
  "description": "Sealed campaigns published autonomously by the company agent.",
  "properties": {
    "campaigns": {
      "items": {
        "$ref": "#/$defs/MarketingCampaign"
      },
      "maxItems": 6,
      "title": "Campaigns",
      "type": "array"
    },
    "objective": {
      "default": "",
      "maxLength": 600,
      "title": "Objective",
      "type": "string"
    },
    "opt_out_reason": {
      "default": "",
      "maxLength": 1000,
      "title": "Opt Out Reason",
      "type": "string"
    }
  },
  "required": [
    "campaigns"
  ],
  "title": "MarketingCampaignSubmission",
  "type": "object"
}

